11	  setSessionId: (id: string | null) => void;
12	  addToolCall: (toolCall: ToolCall) => void;
13	  removeToolCall: (id: string) => void;
14	  clearToolCalls: () => void;
15	  addPermissionRequest: (request: PermissionRequest) => void;
16	  removePermissionRequest: (id: string) => void;
17	  setWidgetVisible: (visible: boolean) => void;
18	  toggleWidget: () => void;
19	}
