21	export const useAppStore = create<AppStore>((set) => ({
22	  status: "idle",
23	  statusMessage: "",
24	  sessionId: null,
25	  toolCalls: [],
26	  permissionRequests: [],
27	  isWidgetVisible: true,
28	
29	  setStatus: (status, message = "") =>
30	    set({ status, statusMessage: message }),
31	
32	  setSessionId: (sessionId) => set({ sessionId }),
33	
34	  addToolCall: (toolCall) =>
35	    set((state) => ({
36	      toolCalls: [toolCall, ...state.toolCalls].slice(0, 5),
37	    })),
38	
39	  removeToolCall: (id) =>
40	    set((state) => ({
41	      toolCalls: state.toolCalls.filter((tc) => tc.id !== id),
42	    })),
43	
44	  clearToolCalls: () => set({ toolCalls: [] }),
45	
46	  addPermissionRequest: (request) =>
47	    set((state) => ({
48	      permissionRequests: [...state.permissionRequests, request],
49	    })),
50	
51	  removePermissionRequest: (id) =>
52	    set((state) => ({
53	      permissionRequests: state.permissionRequests.filter((r) => r.id !== id),
54	    })),
55	
56	  setWidgetVisible: (isWidgetVisible) => set({ isWidgetVisible }),
57	
58	  toggleWidget: () =>
59	    set((state) => ({ isWidgetVisible: !state.isWidgetVisible })),
60	}));
